<?php
namespace App\Console\Commands; use App\Services\Dapcode\InstallationService; use App\Services\Dapcode\IntegrityService; use App\Services\Dapcode\ModuleEncryptionService; use Illuminate\Console\Command; use Illuminate\Support\Facades\File; use Illuminate\Support\Str; class MakeHMVCModule extends Command { protected $signature = 'make:module {name : The name of the new module (e.g. Analytics, Blog, Store)}'; protected $description = 'Create a new HMVC module with Layer 6 Encrypted Protection and AegisGuard BaseController'; public function handle() { $rawName = trim((string) $this->argument('name')); if (empty($rawName)) { $this->error("Nama modul tidak boleh kosong. Contoh: php artisan make:module Blog"); return 1; } $name = Str::studly($rawName); $viewKey = strtolower($name); $modulePath = app_path("Modules/{$name}"); $coreControllerPath = app_path('Http/Controllers/Core'); if (File::isDirectory($modulePath)) { $this->error("Modul [{$name}] sudah ada di dalam direktori app/Modules/{$name}!"); return 1; } $this->info("======================================================="); $this->info("       DAPCODE AEGISGUARD — CREATE NEW MODULE          "); $this->info("======================================================="); $this->line("Membuat struktur modul baru: [{$name}]..."); if ( ! File::isDirectory($coreControllerPath)) { File::makeDirectory($coreControllerPath, 0755, true); } $coreBaseControllerFile = "{$coreControllerPath}/{$name}Controllers.php"; if ( ! File::exists($coreBaseControllerFile)) { $coreStub = "<?php\n\nnamespace App\\Http\\Controllers\\Core;\n\nuse App\\Http\\Controllers\\Controller;\n\nclass {$name}Controllers extends Controller\n{\n    /**\n     * Module name identifier.\n     *\n     * @var string\n     */\n    protected \$moduleName = '{$name}';\n\n    /**\n     * Helper to render view within {$name} module namespace.\n     *\n     * @param string \$view\n     * @param array \$data\n     * @param bool \$return\n     * @return \\Illuminate\\Contracts\\View\\View|string\n     */\n    protected function moduleRender(string \$view, array \$data = [], bool \$return = false)\n    {\n        return parent::moduleRender(\$view, \$data, \$return);\n    }\n}\n"; File::put($coreBaseControllerFile, $coreStub); } File::makeDirectory("{$modulePath}/Controllers", 0755, true); File::makeDirectory("{$modulePath}/Models", 0755, true); File::makeDirectory("{$modulePath}/Views", 0755, true); File::makeDirectory("{$modulePath}/Database/Migrations", 0755, true); $controllerStub = "<?php\n\nnamespace App\\Modules\\{$name}\\Controllers;\n\nuse App\\Http\\Controllers\\Core\\{$name}Controllers;\nuse Illuminate\\Http\\Request;\n\nclass {$name} extends {$name}Controllers\n{\n    /**\n     * Display the index page for {$name} module.\n     * Accessible via: /{$viewKey}\n     *\n     * @param Request \$request\n     * @return \\Illuminate\\Contracts\\View\\View|string\n     */\n    public function index(Request \$request)\n    {\n        \$moduleKey = '{$viewKey}';\n        return \$this->moduleRender('index', [\n            'title' => \"{$name} Module\",\n            'subtitle' => \"DapCode AegisGuard Protected {$name} Module\",\n        ]);\n    }\n}\n"; File::put("{$modulePath}/Controllers/{$name}.php", $controllerStub); $modelStub = "<?php\n\nnamespace App\\Modules\\{$name}\\Models;\n\nuse Illuminate\\Database\\Eloquent\\Factories\\HasFactory;\nuse Illuminate\\Database\\Eloquent\\Model;\n\nclass {$name} extends Model\n{\n    use HasFactory;\n\n    protected \$guarded = [];\n}\n"; File::put("{$modulePath}/Models/{$name}.php", $modelStub); $viewStub = "<div class=\"content-card\">\n    <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; flex-wrap: wrap; gap: 12px;\">\n        <div style=\"min-width: 0; flex: 1;\">\n            <h2 style=\"font-size: 20px; font-weight: 700; color: #fff; margin-bottom: 4px;\">{{ \$title }}</h2>\n            <p style=\"color: var(--text-muted); font-size: 13.5px;\">Modul <strong>{$name}</strong> berhasil dibuat dan terlindungi oleh <strong>DapCode AegisGuard Layer 1–6</strong>.</p>\n        </div>\n    </div>\n\n    <div class=\"stat-item\">\n        <div style=\"font-family: monospace; font-size: 13px; color: #38bdf8; word-break: break-all;\">\n            <i class=\"fa-solid fa-folder-tree\"></i> Controller: app/Modules/{$name}/Controllers/{$name}.php<br>\n            <i class=\"fa-solid fa-cube\"></i> Base Core: app/Http/Controllers/Core/{$name}Controllers.php<br>\n            <i class=\"fa-solid fa-shield-halved\"></i> Security: Encrypted (.enc) Envelope Protection Active\n        </div>\n    </div>\n</div>\n"; File::put("{$modulePath}/Views/index.blade.php", $viewStub); $instId = InstallationService::getInstallationId(); $dummyLic = [ 'license_id' => 'NEW-MOD-' . strtoupper(Str::random(6)), 'installation_id' => $instId, 'status' => 'ACTIVE', 'modules' => ['*'], 'signature' => 'init', ]; $encRes = ModuleEncryptionService::encryptModule($name, $dummyLic); if ($encRes['success']) { ModuleEncryptionService::lockModule($name); $this->info("[SECURITY] Modul [{$name}] berhasil dipaketkan ke dalam format AES-256-GCM (.enc) & di-lock."); } IntegrityService::recordCoreFilesManifest(); $this->info("======================================================="); $this->info("  [BERHASIL] Modul [{$name}] Selesai Dibuat!"); $this->info("======================================================="); $this->line("<comment>Core Base:</comment>    <info>app/Http/Controllers/Core/{$name}Controllers.php</info>"); $this->line("<comment>Encrypted (.enc):</comment> <info>app/Modules/{$name}/Encrypted/</info>"); $this->line("<comment>View Template:</comment> <info>app/Modules/{$name}/Views/index.blade.php</info>"); $this->line("<comment>Access URL:</comment>    <info>/{$viewKey}</info>"); return 0; } }